// WF-07 | Stage 2 - Data Processing
// Turns Webhook / Form / Email / Chat input into ONE canonical envelope.
const DEFAULT_ORG_ID = '11111111-1111-4111-8111-111111111111';
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const CHANNELS = ['webhook', 'form', 'email', 'chat'];

const s = (v, max = 500) => (v === undefined || v === null ? '' : String(v).trim().slice(0, max));
const uuid = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
  const r = (Math.random() * 16) | 0;
  return (c === 'x' ? r : (r & 0x3) | 0x8).toString(16);
});
const hash = (str) => {
  let h1 = 0xdeadbeef, h2 = 0x41c6ce57;
  for (let i = 0; i < str.length; i++) {
    const ch = str.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return (h2 >>> 0).toString(16).padStart(8, '0') + (h1 >>> 0).toString(16).padStart(8, '0');
};
const stripHtml = (h) => String(h || '')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ').trim();

const raw = $json;

// 1) Which trigger fired?
let trigger = 'webhook';
try {
  if ($('01b Form Webhook').isExecuted) trigger = 'form';
  else if ($('01c Email Trigger IMAP').isExecuted) trigger = 'email';
} catch (e) { /* trigger node disabled or missing */ }

// 2) Flatten every channel into the same shape
let input = {};
if (trigger === 'email') {
  const f = raw.from;
  let name = '', address = '';
  if (typeof f === 'string') {
    const m = f.match(/^\s*"?([^"<]*?)"?\s*<([^>]+)>\s*$/);
    if (m) { name = m[1]; address = m[2]; } else { address = f; }
  } else if (f && typeof f === 'object') {
    const v = (Array.isArray(f.value) && f.value[0]) || {};
    name = v.name || '';
    address = v.address || f.text || '';
  }
  const hdr = raw.headers || {};
  input = {
    channel: 'email', source: 'imap', fullName: name, email: address,
    subject: raw.subject,
    message: raw.textPlain || raw.text || stripHtml(raw.textHtml || raw.html),
    messageId: raw.messageId || hdr['message-id'] || (raw.metadata && raw.metadata['message-id']),
    receivedAt: raw.date,
  };
} else {
  const b = raw.body || {};
  const c = b.contact || {};
  input = {
    channel: trigger === 'form' ? 'form' : b.channel,
    source: b.source,
    fullName: b.fullName || b.name || c.fullName || c.name,
    firstName: b.firstName || c.firstName,
    lastName: b.lastName || c.lastName,
    email: b.email || c.email,
    phone: b.phone || c.phone,
    companyName: b.companyName || b.company || c.companyName || c.company,
    subject: b.subject,
    message: b.message || b.text,
    messageId: b.messageId || b.submissionId,
    receivedAt: b.receivedAt || b.submittedAt,
    // the public form must never choose its own organization
    organizationId: trigger === 'webhook' ? b.organizationId : undefined,
    honeypot: b.website,
  };
}

// 3) Normalize values (every length matches the DB column size)
const channel = trigger === 'form' ? 'form'
  : trigger === 'email' ? 'email'
  : (CHANNELS.includes(s(input.channel).toLowerCase()) ? s(input.channel).toLowerCase() : 'webhook');
const source = s(input.source, 40).toLowerCase().replace(/[^a-z0-9._-]/g, '-') || trigger;
const sourceLabel = (source === channel ? channel : channel + ':' + source).slice(0, 80);

let firstName = s(input.firstName, 100);
const lastName = s(input.lastName, 100);
if (!firstName && !lastName && s(input.fullName)) firstName = s(input.fullName, 100); // keep full display name
const companyName = s(input.companyName, 200);

const emailRaw = s(input.email, 320).toLowerCase();
const emailOk = EMAIL_RE.test(emailRaw);
let phone = s(input.phone, 40).replace(/[^\d+]/g, '');
if (/^0\d{9}$/.test(phone)) phone = '+84' + phone.slice(1); // VN local format -> E.164
const phoneDigits = phone.replace(/\D/g, '');
const phoneOk = phoneDigits.length >= 9 && phoneDigits.length <= 15;

const email = emailOk ? emailRaw : '';
const phoneClean = phoneOk ? phone : '';
const identity = email ? 'email:' + email : (phoneClean ? 'phone:' + phoneClean : '');

const subject = s(input.subject, 300);
const message = s(input.message, 5000);

const d = new Date(input.receivedAt || Date.now());
const receivedAt = isNaN(d.getTime()) ? new Date().toISOString() : d.toISOString();

const hCorr = s((raw.headers || {})['x-correlation-id'], 60);
const correlationId = UUID_RE.test(hCorr) ? hCorr.toLowerCase() : uuid();
const organizationId = UUID_RE.test(s(input.organizationId, 60)) ? s(input.organizationId, 60).toLowerCase() : DEFAULT_ORG_ID;

const messageKey = (channel + ':' + (s(input.messageId, 200).replace(/^<|>$/g, '') || hash(identity + '|' + subject + '|' + message))).slice(0, 250);

// 4) Validation (decided here, enforced by node "04 Valid Input?")
const errors = [];
const spam = s(input.honeypot).length > 0;
if (spam) errors.push({ field: 'website', code: 'SPAM', message: 'Yêu cầu bị từ chối.' });
if (emailRaw && !emailOk) errors.push({ field: 'email', code: 'INVALID_EMAIL', message: 'Email không hợp lệ.' });
if (s(input.phone) && !phoneOk) errors.push({ field: 'phone', code: 'INVALID_PHONE', message: 'Số điện thoại không hợp lệ.' });
if (!identity) errors.push({ field: 'contact', code: 'CONTACT_REQUIRED', message: 'Cần ít nhất email hoặc số điện thoại hợp lệ.' });
if (!message && !subject) errors.push({ field: 'message', code: 'MESSAGE_REQUIRED', message: 'Nội dung tin nhắn không được để trống.' });

return {
  json: {
    valid: errors.length === 0,
    errors,
    spam,
    trigger,
    channel,
    source,
    sourceLabel,
    organizationId,
    correlationId,
    messageKey,
    identity,
    contact: { firstName, lastName, companyName, email, phone: phoneClean },
    subject,
    message,
    receivedAt,
    // safe summary for workflow_runs.input (never store headers: they contain secrets)
    runInput: { trigger, channel, source, messageKey, receivedAt },
  },
};

parameters.query:
INSERT INTO workflow_runs (organization_id, workflow_key, n8n_execution_id, status, correlation_id, input)
VALUES ($1::uuid, 'WF-07', $2::text, 'running', $3::uuid, $4::jsonb)
RETURNING id;

UPDATE workflow_runs SET status = 'failed', error = $2::jsonb, finished_at = NOW()
WHERE id = $1::uuid
RETURNING id;

