// WF-07 | Stage 4 - build a Core-API-safe lead body + trace headers.
// Why merge: POST /leads is an upsert that overwrites missing fields with NULL,
// so we re-send the values we already know to avoid wiping them.
const d = $('02 Normalize and Correlate').item.json;
const old = $('05 Load Existing Lead').item.json || {};
const known = !!old.id;

const pickStr = (nv, ov, max) => (nv ? nv : (ov ? String(ov).slice(0, max) : ''));
const oldMeta = (old.metadata && typeof old.metadata === 'object') ? old.metadata : {};

const body = {
  organizationId: d.organizationId,
  externalSource: 'omnichannel',
  externalId: d.identity.slice(0, 160),
  firstName: pickStr(d.contact.firstName, old.first_name, 100),
  lastName: pickStr(d.contact.lastName, old.last_name, 100),
  companyName: pickStr(d.contact.companyName, old.company_name, 200),
  email: pickStr(d.contact.email, old.email, 320),
  phone: pickStr(d.contact.phone, old.phone, 40),
  source: old.source ? String(old.source).slice(0, 80) : d.sourceLabel, // first-touch attribution
  metadata: {
    ...oldMeta,
    ingestion: {
      workflow: 'WF-07',
      lastChannel: d.channel,
      lastSource: d.sourceLabel,
      lastMessageAt: d.receivedAt,
      lastCorrelationId: d.correlationId,
    },
  },
};
// DTO uses @IsEmail/@IsString on optional fields: empty strings are rejected, so drop them.
for (const k of ['firstName', 'lastName', 'companyName', 'email', 'phone']) if (!body[k]) delete body[k];

return { json: { leadBody: body, knownLead: known, idempotencyKey: d.messageKey } };

// WF-07 | Stage 6 - AI/LLM slot, implemented as deterministic rules (no external AI credential needed).
// LLM-based understanding is handled downstream (WF-12 language, WF-13 scoring, WF-19 email triage).
const d = $('02 Normalize and Correlate').item.json;
const text = (d.subject + ' ' + d.message).toLowerCase();

const esc = (w) => w.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const count = (words) => words.reduce((n, w) =>
  n + (new RegExp('(^|[^\\p{L}\\p{N}])' + esc(w) + '($|[^\\p{L}\\p{N}])', 'iu').test(text) ? 1 : 0), 0);

const SALES = ['báo giá', 'bao gia', 'quote', 'pricing', 'giá', 'mua', 'đặt hàng', 'demo', 'dùng thử', 'trial', 'hợp đồng', 'tư vấn', 'purchase', 'buy', 'đăng ký'];
const SUPPORT = ['lỗi', 'không hoạt động', 'bị hỏng', 'hỗ trợ', 'support', 'error', 'bug', 'khiếu nại', 'hoàn tiền', 'refund', 'complaint', 'help', 'sự cố'];
const PARTNER = ['hợp tác', 'partner', 'partnership', 'đối tác', 'tài trợ', 'quảng cáo'];
const URGENT = ['gấp', 'khẩn', 'urgent', 'asap', 'hôm nay', 'ngay'];

const score = { sales_inquiry: count(SALES), support: count(SUPPORT), partnership: count(PARTNER) };
let intent = 'general';
let best = 0;
for (const k of ['sales_inquiry', 'support', 'partnership']) {   // order = tie-break priority
  if (score[k] > best) { best = score[k]; intent = k; }
}
const urgent = count(URGENT) > 0;
const priority = (urgent || (intent === 'sales_inquiry' && best >= 2)) ? 'high' : 'normal';
const language = /[àáạảãâầấậẩẫăằắặẳẵèéẹẻẽêềếệểễìíịỉĩòóọỏõôồốộổỗơờớợởỡùúụủũưừứựửữỳýỵỷỹđ]/i.test(text) ? 'vi' : 'en';

return { json: { intent, priority, language, scores: score, urgent } };

