// WF-07 | Stage 8 - Transformation: build the body for POST /events (event_outbox).
const d = $('02 Normalize and Correlate').item.json;
const lead = $('07 Core API Upsert Lead').item.json.data;   // Core API wraps responses in { data, meta }
const c = $('08 Classify Intent').item.json;

return {
  json: {
    eventBody: {
      eventName: $json.eventName,
      aggregateType: 'lead',
      aggregateId: lead.id,
      organizationId: d.organizationId,
      correlationId: d.correlationId,
      payload: {
        schemaVersion: 1,
        workflow: 'WF-07',
        leadId: lead.id,
        interactionId: $json.id,
        isNewInteraction: $json.created,
        channel: d.channel,
        source: d.sourceLabel,
        intent: c.intent,
        priority: c.priority,
        language: c.language,
        messageKey: d.messageKey,
        receivedAt: d.receivedAt,
        contact: {
          firstName: lead.first_name,
          lastName: lead.last_name,
          companyName: lead.company_name,
          email: lead.email,
          phone: lead.phone,
        },
        subject: d.subject,
        messagePreview: d.message.slice(0, 500),
      },
    },
  },
};

